<?php
require __DIR__.'/app-bootstrap.php';$u=require_admin();require $privateRootPath.'/src/admin_layout.php';
$month=(string)($_GET['month']??date('Y-m',strtotime('first day of last month')));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m',strtotime('first day of last month'));$start=$month.'-01';$end=date('Y-m-t',strtotime($start));
$st=$pdo->prepare("SELECT oi.id order_item_id,o.id order_id,o.paid_at,oi.unit_price_pence,t.title,t.mix_name,GROUP_CONCAT(DISTINCT a.name ORDER BY ta.sort_order,a.name SEPARATOR ', ') artist_names,COUNT(DISTINCT ta.artist_id) artist_count,COUNT(DISTINCT api.artist_id) allocated_count FROM order_items oi JOIN orders o ON o.id=oi.order_id AND o.status='paid' AND DATE(o.paid_at) BETWEEN ? AND ? JOIN tracks t ON t.id=oi.track_id JOIN track_artists ta ON ta.track_id=t.id JOIN artists a ON a.id=ta.artist_id LEFT JOIN artist_payout_items api ON api.order_item_id=oi.id AND api.artist_id=ta.artist_id GROUP BY oi.id,o.id,o.paid_at,oi.unit_price_pence,t.title,t.mix_name ORDER BY o.paid_at DESC,oi.id DESC");$st->execute([$start,$end]);$rows=$st->fetchAll();$hostPercent=payout_host_percent();$gross=0;$host=0;$royalty=0;foreach($rows as &$row){$g=(int)$row['unit_price_pence'];$h=(int)round($g*$hostPercent/100);$pool=max(0,$g-$h);$count=max(1,(int)$row['artist_count']);$row['host_fee_pence']=$h;$row['royalty_pence']=$pool;$row['paid_status']=(int)$row['allocated_count']===(int)$row['artist_count']?'Paid':'Unpaid';$gross+=$g;$host+=$h;$royalty+=$pool;}unset($row);admin_layout_start('Royalty ledger','royalty');
?><div class="section-title"><div><span class="kicker">ARTIST ACCOUNTING</span><h1>Royalty ledger</h1></div><span><?=e($start)?> to <?=e($end)?></span></div><p class="panel muted">Every paid order item is listed once. The host charge is deducted first; the remaining royalty pool is divided equally between the credited artists. A sale is marked paid only when every artist allocation has been included in a payout.</p><form method="get" class="panel admin-compact-form"><label>Calendar month<select name="month" onchange="this.form.submit()"><?php for($y=(int)date('Y');$y>=(int)date('Y')-3;$y--):?><?php for($m=1;$m<=12;$m++):$value=sprintf('%04d-%02d',$y,$m);?><option value="<?=$value?>" <?=$value===$month?'selected':''?>><?=date('F Y',strtotime($value.'-01'))?></option><?php endfor;?><?php endfor;?></select><small>Host charge: <?=number_format($hostPercent,2)?>%</small></label></form><div class="admin-stat-grid"><div class="panel admin-stat"><span>Gross sales</span><strong><?=money($gross)?></strong></div><div class="panel admin-stat"><span>Host charge</span><strong><?=money($host)?></strong></div><div class="panel admin-stat"><span>Artist royalty pool</span><strong><?=money($royalty)?></strong></div></div><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Sales reconciliation</h2><span><?=count($rows)?> sale<?=count($rows)===1?'':'s'?></span></div><?php if(!$rows):?><p class="muted">No paid sales were recorded in this period.</p><?php else:?><div class="admin-table royalty-table"><div class="admin-row user-admin-head"><strong>Order</strong><strong>Track</strong><strong>Artist(s)</strong><strong>Gross</strong><strong>Host fee</strong><strong>Royalty</strong><strong>Status</strong></div><?php foreach($rows as $row):?><div class="admin-row"><span>#<?=e($row['order_id'])?><small><?=e($row['paid_at'])?></small></span><span><strong><?=e($row['title'])?></strong><?php if($row['mix_name']):?><small><?=e($row['mix_name'])?></small><?php endif;?></span><span><?=e($row['artist_names'])?></span><span><?=money((int)$row['unit_price_pence'])?></span><span><?=money((int)$row['host_fee_pence'])?></span><span><strong><?=money((int)$row['royalty_pence'])?></strong></span><span class="badge <?=$row['paid_status']==='Paid'?'paid':'pending'?>"><?=e($row['paid_status'])?></span></div><?php endforeach;?></div><?php endif;?></section><?php admin_layout_end();
